/**
 * npm run paste — builds the 3 files for deploying without the command line:
 *   paste/Code.gs          all server code in one file
 *   paste/index.html       the app page
 *   paste/appsscript.json  the project manifest
 * Paste them into a script.google.com project (see docs/DEPLOY-IN-BROWSER.md).
 */
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
execSync('node build.mjs', { cwd: ROOT, stdio: 'inherit' });
const dist = path.join(ROOT, 'dist');
const out = path.join(ROOT, 'paste');
fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(out);
const files = fs.readdirSync(dist).filter((f) => f.endsWith('.js')).sort();
const code = [
  '/**',
  ' * Tax Manager — all server code in one file (generated by `npm run paste`).',
  ' * Source: tax-manager/src/server/*.js. Built ' + new Date().toISOString().slice(0, 10) + '.',
  ' */',
  '',
  ...files.map((f) => `// ==================== ${f} ====================\n` + fs.readFileSync(path.join(dist, f), 'utf8')),
].join('\n');
fs.writeFileSync(path.join(out, 'Code.gs'), code);
fs.copyFileSync(path.join(dist, 'index.html'), path.join(out, 'index.html'));
fs.copyFileSync(path.join(dist, 'appsscript.json'), path.join(out, 'appsscript.json'));
console.log('Wrote paste/Code.gs, paste/index.html, paste/appsscript.json');
